import{_ as r,o,c as i,a2 as t}from"./chunks/framework.LJP3gfxI.js";const h=JSON.parse('{"title":"0001 — Provider v1 keeps Form versions independent","description":"","frontmatter":{},"headers":[],"relativePath":"spec/decisions/0001-provider-v1-keeps-form-versions-independent.md","filePath":"spec/decisions/0001-provider-v1-keeps-form-versions-independent.md"}'),a={name:"spec/decisions/0001-provider-v1-keeps-form-versions-independent.md"};function n(d,e,s,c,l,p){return o(),i("div",null,[...e[0]||(e[0]=[t('<h1 id="_0001-—-provider-v1-keeps-form-versions-independent" tabindex="-1">0001 — Provider v1 keeps Form versions independent <a class="header-anchor" href="#_0001-—-provider-v1-keeps-form-versions-independent" aria-label="Permalink to &quot;0001 — Provider v1 keeps Form versions independent&quot;">​</a></h1><ul><li>Status: accepted</li><li>Date: 2026-07-29</li><li>Owners: Takoform maintainers</li><li>Subsequent decision: <a href="./0002-artifact-urls-are-credential-free-state.html">0002</a> advances the current artifact-backed Form identities without changing this version-independence decision.</li></ul><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>The active provider successor removes <code>takoform_http_service</code> and introduces <code>takoform_edge_worker</code>. This is a breaking provider resource transition, so it is the appropriate boundary for the first stable provider major.</p><p>The exact transition audit also found that all 33 Form kinds common to provider v0.2.1 and the v1 candidate changed their exact FormRef/package identity. A direct refresh through v1 could otherwise query a new exact identity, receive <code>404</code> for an old Resource, and remove its state.</p><p>The published <code>v0.2.x</code> provider also exposed a writable <code>takoform_interface</code> resource. That write path duplicates host authority: portable projects may declare Interface descriptors inside Form Definitions and read the resulting projection, while Interface records, bindings, authorization, write fencing, and lifecycle belong to the host.</p><p>Takoform also has multiple public version streams. Provider versions identify provider binaries. A Form definition version is part of an exact <code>FormRef</code>; its canonical bytes are bound by <code>schemaDigest</code>. Form Package versions and admission generations have separate identities and lifecycles.</p><p>Public Form Package releases already occupy <code>EdgeWorker@1.0.0</code> and <code>EdgeWorker@1.0.1</code>. The current provider-neutral EdgeWorker definition has different bytes and schema.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><p>The successor provider candidate is <code>v1.0.0</code>. Provider compatibility follows SemVer: breaking changes to an existing <code>v1.x</code> resource type or persisted state require provider <code>v2</code>.</p><p>Form definition versions, Form Package versions, and admission generations remain independent. The provider-neutral Form introduced by this decision was <code>EdgeWorker@2.0.0</code>; provider <code>v1.0.0</code> did not reset it to <code>1.0.0</code>. Decision 0002 later advances the current artifact-backed identity to <code>EdgeWorker@3.0.0</code> without changing this rule. <code>ga-core-v2</code> also remains an independent admission-generation identifier.</p><p>The portable API group remains <code>forms.takoform.com/v1alpha1</code>. Provider v1 therefore means a stable Terraform/OpenTofu provider surface, not a stable portable specification or completed admission.</p><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><ul><li>Existing <code>takoform_http_service</code> state remains pinned to provider <code>v0.2.1</code> until an operator performs an explicit create, cutover, and destroy migration.</li><li>All other v0.2.1 Form resource state remains pinned too. Provider v1 starts resource schema version <code>1</code>, records the exact FormRef/package identity in computed state, and rejects version <code>0</code> through a diagnostic-only handler that returns no transformed state and makes no Resource lifecycle request.</li><li>Provider <code>v1.0.0</code> exposes <code>takoform_edge_worker</code>. This decision introduced it for <code>EdgeWorker@2.0.0</code>; decision 0002 advances the current exact Form identity to <code>EdgeWorker@3.0.0</code>.</li><li>Provider <code>v1.0.0</code> removes the writable <code>takoform_interface</code> resource and retains only the read-only data source. Existing resource state must be reconciled under <code>v0.2.1</code> before upgrade; it is not silently reinterpreted.</li><li>Published Form versions and bytes are never overwritten to make version numbers look aligned.</li><li>Future breaking provider resource or state changes require a new provider major even if the affected Form has a different major.</li><li>An old OpenTofu provider address is normalized only through an explicit <code>state replace-provider</code>; address replacement never migrates a Form identity.</li></ul><h2 id="rejected-alternatives" tabindex="-1">Rejected alternatives <a class="header-anchor" href="#rejected-alternatives" aria-label="Permalink to &quot;Rejected alternatives&quot;">​</a></h2><ul><li><strong>Republish <code>EdgeWorker@1.0.0</code>.</strong> Rejected because it would assign different bytes to an immutable public identity.</li><li><strong>Make every Form and admission generation <code>1.0.0</code>.</strong> Rejected because those identities change for different reasons and coordinated numbering would create false compatibility claims.</li><li><strong>Keep the breaking provider transition on <code>v0.3.0</code>.</strong> Rejected because the transition is the clean boundary for declaring and enforcing the provider v1 compatibility contract.</li></ul>',16)])])}const m=r(a,[["render",n]]);export{h as __pageData,m as default};
